## functions

namespace functions {

// Busca un docente por nombre (parcial, sin distinguir mayúsculas/tildes). Devuelve su id real. Si no hay coincidencia, la respuesta es DOCENTE_NOT_FOUND con context.sugerencias — una lista de nombres reales parecidos (posible error de tipeo). Nunca respondas "no existe" sin revisar antes si vino esa lista: si vino, proponé esos nombres al usuario ("¿Quisiste decir...?") en vez de cortar la conversación.
type buscar_docente_por_nombre = (_: {
// Nombre o parte del nombre del docente
 // constraints: minLength: 2
nombre: string,
// additional properties: not allowed
}) => any;

// Lista DJs visibles para el usuario autenticado. Para encontrar la DJ de un docente puntual, llamala SOLO con docenteId (sin estado) — no adivines ni asumas un estado como filtro. Usá "estado" únicamente si el usuario pidió explícitamente filtrar por un estado conocido.
type listar_declaraciones_juradas = (_: {
// Id real de docente
docenteId?: string | null,
estado?:

 | "BORRADOR" | "EN_REVISION_FACULTAD" | "APROBADA" | "DEVUELTA" | "EN_REVISION_DPA" | "RECHAZADA"
 | null
,
// additional properties: not allowed
}) => any;

// Detalle completo de una DJ por id real (nunca inventado — usar el id de listar_declaraciones_juradas).
type consultar_declaracion_jurada = (_: {
// Id real, de listar_declaraciones_juradas
 // constraints: minLength: 1
djId: string,
// additional properties: not allowed
}) => any;

// Reglas válidas (roles, si pide observaciones/misma facultad/vinculación activa) desde un estado de DJ. Usar el estado REAL de una DJ específica (de listar_declaraciones_juradas) — nunca un estado adivinado.
type consultar_reglas_transicion = (_: {
// Estado real, nunca adivinado
estado: "BORRADOR" | "EN_REVISION_FACULTAD" | "APROBADA" | "DEVUELTA" | "EN_REVISION_DPA" | "RECHAZADA",
// additional properties: not allowed
}) => any;

// ESCRITURA — cambia el estado de una DJ (ENVIAR/APROBAR/DEVOLVER/ESCALAR_DPA/REENVIAR/RECHAZAR). Se pausa para confirmación humana — no asumas que ya se ejecutó.
type transicionar_declaracion_jurada = (_: {
comando: "ENVIAR" | "APROBAR" | "DEVOLVER" | "ESCALAR_DPA" | "REENVIAR" | "RECHAZAR",
// Id real, de listar_declaraciones_juradas
 // constraints: minLength: 1
djId: string,
observaciones?:

 | string
 | null
,
// additional properties: not allowed
}) => any;

} // namespace functions

